package in.kabadiwala.connect.model; import org.springframework.data.annotation.*; import org.springframework.data.mongodb.core.index.*; import org.springframework.data.mongodb.core.mapping.Document; import java.time.Instant; import java.util.*; @Document("recycler_profiles") public class RecyclerProfile {@Id public String id; @Indexed(unique=true) public String userId; public String businessName,authorizedPerson,address,city,state,pincode,licenseNumber; public List<String> serviceAreas=new ArrayList<>(),categoryIds=new ArrayList<>(),documentIds=new ArrayList<>(); public String verificationStatus="PENDING_VERIFICATION",verificationReason; public List<VerificationEvent> verificationHistory=new ArrayList<>(); @CreatedDate public Instant createdAt; @LastModifiedDate public Instant updatedAt; public record VerificationEvent(String status,String adminId,String reason,Instant at){}}